/* Service worker: makes Bloomdoku installable and fully offline.
 * The cache list and version below are GENERATED by tools/update-sw.py (run it after editing any file).
 * Each release is cached atomically under its own name and old caches are deleted, so nobody runs a mix of old
 * and new files. */
const VERSION = 'bloom-e547f986a3';
const SHELL = [
  /* BEGIN SHELL */
  './',
  'css/style.css',
  'icons/apple-touch-icon.png',
  'icons/favicon.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon-maskable-512.png',
  'icons/icon.svg',
  'index.html',
  'js/app.js',
  'js/art.js',
  'js/cloud.js',
  'js/core.js',
  'js/engine.js',
  'js/es.js',
  'js/friends.js',
  'js/game.js',
  'js/shop.js',
  'js/sound.js',
  'js/worlds.js',
  'manifest.webmanifest'
  /* END SHELL */
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(VERSION)
      .then((cache) => cache.addAll(SHELL.map((url) => new Request(url, { cache: 'reload' }))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('bloom-') && k !== VERSION).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
      if (res.ok) { const copy = res.clone(); caches.open(VERSION).then((c) => c.put(req, copy)); }
      return res;
    }))
  );
});
